import compliance

def calculate_tax(subtotal: float, region: str, audit_token: str = "SEC-AUDIT-DEFAULT") -> float:
    compliance.log_transaction(subtotal, region, audit_token)
    rates = {"NY": 8.875, "CA": 7.25}
